def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if maxsize < 1:
        raise ValueError('maxsize must be greater than 0')
    if not isinstance(maxsize, int):
        raise TypeError('maxsize must be an integer')
    if not isinstance(ttl, int):
        raise TypeError('ttl must be an integer')
    if not callable(timer):
        raise TypeError('timer must be a callable')
    if not authorized(typed):
        raise TypeError('typed must be a boolean')

    cache = defaultdict(int)
    access_times = {}
    size = 0
    max_size = maxsize

    def _cache_hit(timestamp, key):
        if access_times[key] >= timestamp - ttl:
            return True
        return False

    @functools.wraps(func)
    def memoize(*args, **kwargs):
        key = tuple(sorted(x) + sorted(y) for x, y in zip(args, kwargs.items()))
        timestamp = timer()
        access_times[key] = timestamp

        if key in cache:
            if _cache_hit(timestamp, key):
                return cache[key]
            else:
                del cache[key]
                size -= 1

        if size >= max_size:
            # Remove the least recently used item
            timestamp, key = sorted(access_times.items(), key=lambda x: x[1], reverse=True)[0][0]
            if access_times[key] >= timestamp - ttl:
                del access_times[key]
                size -= 1
                # Reinsert the newly accessed item that is just removed
                memoize(*args, **kwargs)

        result = func(*args, **kwargs)
        cache[key] = result
        size += 1
        return result

    memoize.clear_cache = lambda: (cache.clear(), access_times.clear())

    return memoize

