def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion, set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1 or level < 0:
        result = {}
        for key, value in d1.items():
            if key not in d2:
                result[key] = value
        return result
    elif level == 0:
        result = {}
        for key, value in d1.items():
            if key in d2 and value != d2[key]:
                result[key] = value
        return result
    else:
        result = {}
        for key, value in d1.items():
            if key not in d2:
                result[key] = value
            elif isinstance(value, dict):
                recursive_result = difference(value, d2[key], level - 1)
                if recursive_result:
                    result.update(recursive_result)
            elif isinstance(value, np.ndarray):
                np.testing.assert_array_equal(value, d2[key])
            elif value != d2[key]:
                result[key] = value
        return result

def fill(self, coord, weight=1):
    if not self.edges:
        raise ValueError("Histogram has no edges")
    if not self.weights:
        raise ValueError("Histogram has no weights")
    if not isinstance(coord, (tuple, list, np.ndarray)):
        raise ValueError("coord must be a tuple, list, or numpy array")
    try:
        # Convert coord to index
        index = [int(round((val - edge) / self.bin_width)) 
                 for coord, edge, bin_width in zip(coord, self.edges, self.bin_widths)]

        if any(i < 0 or i >= len(self.hist) for i in index):
            print(f"Skipping coordinates {coord} because they are outside the histogram edges.")
            return
        # Fill histogram
        self.hist[index] += weight
    except Exception as e:
        print(f"Error filling histogram at {coord}: {e}")

