def render(pieces, style):
    """Render the given version pieces into the requested style."""

    opts = style.opts
    render_droids = []

    if opts.shortcuts is None:
        opts.shortcuts = {}

    extra_properties = {}
    if opts.extra_properties is None:
        opts.extra_properties = {}

    # Create a list of render_droids that will be used to create the template
    for piece in pieces:
        if piece['type'] == 'segment':
            segment = piece['segment']
            if segment['type'] == 'nested':
                nested_segments = segment['segments']
                tmp_segment = Segment()
                tmp_segment.text = segment['text']
                tmp_segment.type = 'paragraph'
                if 'margin-top' in nested_segments[0]['opts'].keys():
                    opts.margin_top = nested_segments[0]['opts']['margin-top']
                elif 'margin-bottom' in nested_segments[0]['opts'].keys():
                    opts.margin_bottom = nested_segments[0]['opts']['margin-bottom']
                for segment in nested_segments:
                    new_segment = Segment()
                    new_segment.text = segment['text']
                    new_segment.type = segment['type']
                    new_segment.opts = segment['opts']
                    tmp_segment.segments.append(new_segment)
                render_droids.append(tmp_segment)
            else:
                render_droids.append(Segment(segment['text'], segment['type'], opts, extra_properties))
        else:
            render_droids.append(Segment(piece['text'], piece['type']))

    # Finally, return the rendered droids
    return render_droids

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""

    has_plus = False
    for piece in pieces:
        if math.isnan(piece) or piece == 0.0:
            return '.'

        if piece > 0.0:
            if has_plus:
                return '+. '
            else:
                has_plus = True
                return '+ '

    return '.'

def run_command(self, commands: List[str], args: List[str], cwd: Optional[str] = None, verbose: bool = False, hide_stderr: bool = False, env: Optional[dict] = None) -> None:
        """Call the given command(s)."""
        args = [cmd * (i == 0) for i, cmd in enumerate(commands)]
        args = [' '.join(tokens) for tokens in args]

        try:
            result = subprocess.run(args, cwd=cwd, shell=False, stdout=subprocess.PIPE, stderr=subprocess.PIPE if not hide_stderr else sys.stdout, env=env)
            if not verbose:
                result.stdout = None
                result.stderr = None
            if result.returncode != 0:
