def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_subparsers = {}
    remaining_args = []

    for arg in unparsed_arguments:
        for name, parser in subparsers.items():
            if parser.match(arg):
                parsed_args = parser.parse_known_args([arg])[0]
                parsed_subparsers[name] = parsed_args
                break
        else:
            remaining_args.append(arg)

    return parsed_subparsers, remaining_args

def deep_merge_nodes(nodes):
    # Use a dictionary to map each key to its corresponding values.
    merged_dict = {}

    for key, value in nodes:
        # If the key already exists, we have a conflict.
        if key in merged_dict:
            # Flatten and merge the values if they are ListNodes.
            if isinstance(merged_dict[key], dict) and isinstance(value, dict):
                if isinstance(merged_dict[key].get('value'), list) and isinstance(value.get('value'), list):
                    merged_dict[key]['value'].extend(value['value'])
            else:
                merged_dict[key].append(value)
        # Otherwise, we simply store the value.
        else:
            merged_dict[key] = value

    # Convert the dictionary back to a list of tuples.
    merged_nodes = [(key, value) for key, value in merged_dict.items()]

    return merged_nodes

