def _resolve_string(matcher):
    '''_get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.'''
    if matcher is None or not ((isinstance(matcher, dict) and 'name' in matcher) or isinstance(matcher, str)):
        raise ValueError('Invalid input: matcher must be a dictionary with a "name" key or a string')

    name = matcher.get('name')
    default = matcher.get('default')

    if name not in os.environ:
        if default is not None:
            return default
        raise ValueError(f'Environment variable {name} not found')

    value = os.environ[name]

    if default is not None and value == '':
        return default

    return int(value) if value.isdigit() and int(value) == float(value) else value

