        if parent not in node_set:
            node_set.add(parent)
            for parent_of_parent in graph.direct_successors(parent):
                add_parents(parent_of_parent, node_set)

    all_roots = set()

    for node in graph.nodes():
        seen = set()
        parents = {graph.predecessors(node)[0]}
        add_parents(node, seen)

        if node in seen and len(seen) == 1:
            all_roots.add(node)

    return all_roots

