    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    metaclass = None

    # Check explicit __metaclass__
    if explicit_mc:
        if isinstance(explicit_mc, type):
            metaclass = explicit_mc
        else:
            raise ValueError("explicit_mc must be a type")

    # Check direct metaclass argument in bases
    for base in bases:
        try:
            baseobj = base.infer()
            if baseobj.is_class and baseobj.is_type:
                metaclass = baseobj._metaclass
                break
        except exceptions.InferenceError:
            pass

    # Check global metaclass variable
    if not metaclass:
        try:
            global_metaclass = globals().get('__metaclass__')
            if global_metaclass:
                metaclass = global_metaclass
        except KeyError:
            pass

    return metaclass

