def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""

        if not self._head or not self._tail:
            raise KeyError('list is empty')

        least_used_node = self._head
        for node in self._head[2:]:
            if node[2] < least_used_node[2]:
                least_used_node = node

        self._remove(least_used_node)
        return (least_used_node[0], least_used_node[1][0])

