def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    # Retrieve the arguments specified in the argument_spec dictionary
    arguments = {item[0]: item[1] for item in self.argument_spec.items()}

    # Retrieve the arguments specified in the additional arguments dictionary
    additional_args = {item[0]: item[1] for item in self.additional_args.items() if item[0] in arguments}

    # Retrieve the arguments specified in the environment variables
    env_args = {k: os.environ[k] for k in self.arguments.keys() if k in os.environ}

    # Update the arguments with the values retrieved from the environment variables
    arguments.update(env_args)

    # Retrieve the default values specified in the spec and other sources
    defaults = {
        k: v.default_value if isinstance(v.default_value, str) else v.default_value() if callable(v.default_value) else v.default_value
        for k, v in self.arguments.items()
    }

    # Update the arguments with the default values
    arguments.update(defaults)

    return arguments

