def validate_arg_deprecation(self, cli_args: Dict[str, Any], answer_file_args: Dict[str, Any]) -> None:
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_arg_mapping = {
        'old_arg1': 'new_arg1',
        'old_arg2': 'new_arg2'
    }

    for old_arg, new_arg in deprecated_arg_mapping.items():
        if old_arg in cli_args and cli_args[old_arg] is not None:
            warnings.warn(f'Keyword argument "{old_arg}" has been deprecated in favour of "{new_arg}". '
                          f'"{old_arg}" will be removed in a future version.',
                          category=DeprecationWarning,
                          stacklevel=2,
                      )
            cli_args[new_arg] = cli_args.pop(old_arg)

    for old_arg, new_arg in deprecated_arg_mapping.items():
        if old_arg in answer_file_args and answer_file_args[old_arg] is not None:
            warnings.warn(f'Keyword argument "{old_arg}" has been deprecated in favour of "{new_arg}". '
                          f'"{old_arg}" will be removed in a future version.',
                          category=DeprecationWarning,
                          stacklevel=2,
                      )
            answer_file_args[new_arg] = answer_file_args.pop(old_arg)

