def validate_requires_args(self, args):
    if not args:
        raise ValueError("No arguments provided.")
    missing_args = [arg for arg in self.args if arg not in args]
    if missing_args:
        raise ValueError(f"Missing required arguments: {', '.join(missing_args)}")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if arg_value is not None:
            continue
        raise ValueError(f"Missing required argument: {arg_name}")

def validate_choices_args(self, args):
    # Assuming choices is a dictionary containing available choices for each argument
    for arg, value in args.items():
        if isinstance(value, str) and value not in choices.get(arg, []):
            raise ValueError(f"Invalid choice for {arg}: {value}. Available choices: {choices.get(arg, [])}")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not isinstance(args, (list, tuple)):
        raise TypeError("Invalid input type. The inputs must be a list or tuple.")

    min_val = args[0]
    max_val = args[1]

    if not isinstance(min_val, (int, float)):
        raise TypeError("Invalid first input type. The first input must be an integer or float.")

    if not isinstance(max_val, (int, float)):
        raise TypeError("Invalid second input type. The second input must be an integer or float.")

    if min_val >= max_val:
        raise ValueError("Minimum value should be less than maximum value.")

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Collect control arguments
    for arg in args:
        if arg.startswith('control_'):
            control_args[arg] = arg[7:]

    # Collect nested arguments
    for arg in args:
        if arg.startswith('nested_'):
            nested_args[arg] = arg[7:]

    # Collect custom arguments
    for arg in args:
        if arg.startswith('custom_'):
            custom_args[arg] = arg[7:]

    return (control_args, nested_args)

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """

        if extra_vars is None:
            return vars_dict
        else:
            if not isinstance(vars_dict, dict):
                raise ValueError("vars_dict must be a dictionary")
            if not isinstance(extra_vars, list):
                raise ValueError("extra_vars must be a list")
            for extravar in extra_vars:
                if not isinstance(extravar, dict):
                    raise ValueError("extravars must be a dictionary")
                vars_dict.update(extravar)
            return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # This function assumes that the arguments are names that match the 'id' attribute in the 'self' list
    # For example, if self has the attribute 'port', then values_dict will have a key 'port'
    # The function checks if the key exists in values_dict and if it does, it attempts to convert it to an integer
    for key in values_dict:
        attr = getattr(self, key, None)
        if attr is not None:
            try:
                values_dict[key] = int(values_dict[key])
            except ValueError:
                pass

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    spec_dict = {}
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith('.json'):
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    plugin_spec = json.load(f)
                    spec_dict.update(plugin_spec)
    return spec_dict

